extends SceneTree

func _init() -> void:
	print("Running theme lab automated tests...")
	var main_scene = load("res://scenes/main.tscn")
	if not main_scene:
		printerr("Failed to load main scene!")
		quit(1)
		return

	var root = main_scene.instantiate()
	if not root:
		printerr("Failed to instantiate main scene!")
		quit(1)
		return

	root_node_added(root)

	print("Root theme: ", root.theme)

	var default_button = root.get_node("MainPanel/DefaultButton")
	print("DefaultButton theme_owner: ", default_button.theme)
	print("DefaultButton font_color: ", default_button.get_theme_color("font_color", "Button"))
	print("Root font_color: ", root.get_theme_color("font_color", "Button"))

	quit(0)

func root_node_added(node: Node) -> void:
	get_root().add_child(node)
